import type {
  ISliderController,
  InputConfig,
  InputCallbacks,
} from '../core/types';
import type { Sprite } from 'pixi.js';
import {
  DEFAULT_INPUT_CONFIG,
  PHYSICS,
  EVENT_NAMES,
  HTML_TAGS,
  HTML_ATTRIBUTES,
  KEYBOARD_KEYS,
} from '../core';
import { EventThrottler } from './event-throttler';
import { GestureRecognizer, GestureType, GestureInfo } from './gesture-recognizer';
import { KeyboardNavigator, KeyboardCallbacks } from './keyboard-navigator';
// Phase 2.1 GSAP Physics Integration
import { 
  KineticPhysics, 
  GSAPTimelineFactory, 
  SpringPhysics, 
  VelocityTracker 
} from '../physics';

/**
 * SliderController - Enhanced input handling with modern patterns
 *
 * Phase 2.2 enhanced input controller featuring:
 * - Modern Pointer Events API for unified input handling
 * - Advanced gesture recognition with multi-touch support
 * - Performance-optimized event throttling with RAF alignment
 * - Full accessibility compliance (WCAG 2.1 AA)
 * - Physics-driven gesture classification
 * - Input validation and security
 *
 * Key Features:
 * - Unified pointer events (mouse, touch, pen)
 * - Advanced gesture recognition (swipe, pinch, tap, long-press)
 * - RAF-aligned event throttling for 60fps performance
 * - Full keyboard accessibility with screen reader support
 * - Physics integration for natural gesture feedback
 * - Cross-platform compatibility
 *
 * @example
 * ```typescript
 * const controller = new SliderController();
 * controller.initialize(element, {
 *   onSwipeLeft: () => nextSlide(),
 *   onSwipeRight: () => prevSlide(),
 *   onGesture: (gesture) => handleAdvancedGesture(gesture)
 * });
 * ```
 */
export class SliderController implements ISliderController {
  private config: InputConfig = DEFAULT_INPUT_CONFIG;

  private callbacks: InputCallbacks | null = null;
  private element: HTMLElement | null = null;
  private isEnabled = false;

  // Enhanced Phase 2.2 components
  private eventThrottler: EventThrottler;
  private gestureRecognizer: GestureRecognizer | null = null;
  private keyboardNavigator: KeyboardNavigator | null = null;

  // Phase 2.1 GSAP Physics Integration
  private kineticPhysics: KineticPhysics;
  private springPhysics: SpringPhysics;
  private velocityTracker: VelocityTracker;

  // Legacy Touch/Mouse state (maintained for compatibility)
  private isPointerDown = false;
  private startX = 0;
  private startY = 0;
  private currentX = 0;
  private currentY = 0;
  private startTime = 0;

  // Event listeners for cleanup
  private boundHandlers = new Map<string, EventListener>();

  constructor() {
    // Initialize event throttler with performance optimization
    this.eventThrottler = new EventThrottler({
      useRAF: true,
      enableMetrics: true,
      maxBatchSize: 10,
    });

    // Initialize Phase 2.1 GSAP Physics components
    this.kineticPhysics = new KineticPhysics();
    this.springPhysics = new SpringPhysics();
    this.velocityTracker = new VelocityTracker();
  }

  /**
   * Initialize enhanced input handling on target element
   */
  initialize(element: HTMLElement, callbacks: InputCallbacks): void {
    this.element = element;
    this.callbacks = callbacks;

    // Initialize enhanced components
    this.setupGestureRecognizer();
    this.setupKeyboardNavigator();
    this.setupEventListeners();
    this.enable();
  }

  /**
   * Setup advanced gesture recognition
   */
  private setupGestureRecognizer(): void {
    if (!this.element) return;

    this.gestureRecognizer = new GestureRecognizer(this.element, {
      enableMultiTouch: true,
      swipeThreshold: this.config.swipeThreshold,
      tapThreshold: this.config.dragThreshold,
    });

    // Handle gesture events
    this.gestureRecognizer.onGesture = (gesture: GestureInfo): void => {
      this.handleGesture(gesture);
    };
  }

  /**
   * Setup accessible keyboard navigation
   */
  private setupKeyboardNavigator(): void {
    if (!this.element || !this.callbacks) return;

    const keyboardCallbacks: KeyboardCallbacks = {
      onNext: () => this.callbacks?.onSwipeLeft(), // Next slide
      onPrevious: () => this.callbacks?.onSwipeRight(), // Previous slide
      onFirst: () => {
        // Could add onGoToSlide callback for first slide
        this.callbacks?.onKeyLeft();
      },
      onLast: () => {
        // Could add onGoToSlide callback for last slide
        this.callbacks?.onKeyRight();
      },
      onTogglePlayPause: () => {
        // Delegate to input callbacks which connect to SliderEngine
        if (this.callbacks?.onTogglePlayPause) {
          this.callbacks.onTogglePlayPause();
        }
      },
      onGoToSlide: (index: number) => {
        // Delegate to input callbacks which connect to SliderEngine
        if (this.callbacks?.onGoToSlide) {
          this.callbacks.onGoToSlide(index);
        }
      },
      onEscape: () => {
        // Delegate to input callbacks which connect to SliderEngine
        if (this.callbacks?.onEscape) {
          this.callbacks.onEscape();
        }
      },
    };

    this.keyboardNavigator = new KeyboardNavigator(
      this.element,
      keyboardCallbacks,
      {
        enableArrowKeys: this.config.enableKeyboard,
        enableWASD: this.config.enableKeyboard,
        respectMotionPreferences: true,
        enableAnnouncements: true,
      }
    );
  }

  /**
   * Handle advanced gesture events with GSAP physics integration
   */
  private handleGesture(gesture: GestureInfo): void {
    if (!this.callbacks || !this.isEnabled) return;

    // Update velocity tracker with gesture data
    this.velocityTracker.addSample(
      gesture.currentPoint.x,
      gesture.currentPoint.y,
      performance.now()
    );

    // Map gesture types to physics-driven callback actions
    switch (gesture.type) {
      case GestureType.SWIPE_LEFT:
        this.handlePhysicsSwipe(gesture, 'left');
        break;
      case GestureType.SWIPE_RIGHT:
        this.handlePhysicsSwipe(gesture, 'right');
        break;
      case GestureType.TAP:
        this.handlePhysicsTap(gesture);
        break;
      case GestureType.DOUBLE_TAP:
        this.handlePhysicsDoubleTap(gesture);
        break;
      case GestureType.LONG_PRESS:
        this.handlePhysicsLongPress(gesture);
        break;
      case GestureType.PINCH:
        this.handlePhysicsPinch(gesture);
        break;
      case GestureType.PAN:
        this.handlePhysicsPan(gesture);
        break;
    }
  }

  /**
   * Handle swipe gestures with kinetic physics and GSAP animations
   */
  private handlePhysicsSwipe(gesture: GestureInfo, direction: 'left' | 'right'): void {
    // Calculate kinetic momentum using our physics engine
    const momentum = this.kineticPhysics.calculateMomentum(
      gesture.velocity,
      gesture.distance,
      gesture.duration
    );

    // Create physics-driven GSAP momentum animation
    if (this.element) {
      // Note: GSAP Timeline Factory expects Sprite but we're using DOM elements
      // Using 'unknown' type assertion as architectural bridge between DOM and PIXI systems
      const feedbackTimeline = GSAPTimelineFactory.createMomentumAnimation(
        this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
        {
          velocity: momentum.velocity,
          direction: direction === 'left' ? -1 : 1,
          duration: momentum.duration,
          damping: 0.85,
        }
      );

      // Apply drag effect for immediate feedback
      const dragFeedback = GSAPTimelineFactory.createDragEffect(
        this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
        gesture.distance,
        0.1 // Subtle scale intensity
      );

      // Play both animations
      feedbackTimeline.play();
      dragFeedback.play();
    }

    // Trigger the appropriate callback
    if (direction === 'left') {
      this.callbacks?.onSwipeLeft();
    } else {
      this.callbacks?.onSwipeRight();
    }
  }

  /**
   * Handle tap gestures with spring physics feedback
   */
  private handlePhysicsTap(_gesture: GestureInfo): void {
    if (!this.element) return;

    // Create subtle scale feedback for tap using GSAP
    const tapFeedback = GSAPTimelineFactory.createScaleAnimation(
      this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
      {
        targetScale: 0.98,
        baseScale: 1.0,
        duration: 0.1,
        ease: 'power2.out',
      }
    );

    // Reset scale immediately after
    setTimeout(() => {
      const resetFeedback = GSAPTimelineFactory.createScaleReset(
        this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
        1.0
      );
      resetFeedback.play();
    }, 100);

    tapFeedback.play();
  }

  /**
   * Handle double-tap with enhanced spring feedback
   */
  private handlePhysicsDoubleTap(_gesture: GestureInfo): void {
    if (!this.element) return;

    // Create more pronounced bounce feedback for double-tap
    const bounceFeedback = this.springPhysics.createBouncyScale(
      this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
      1.05, // Peak scale
      1.0,  // Final scale
      2     // Bounce count
    );

    bounceFeedback.play();
  }

  /**
   * Handle long press with progressive spring effect
   */
  private handlePhysicsLongPress(_gesture: GestureInfo): void {
    if (!this.element) return;

    // Create spring scale effect for long press
    const springFeedback = this.springPhysics.createScaleSpring(
      this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
      1.02, // Slight scale increase
      {
        springConstant: 0.2,
        damping: 0.8,
        duration: 0.3,
        ease: 'elastic.out(1, 0.5)',
      }
    );

    springFeedback.play();
  }

  /**
   * Handle pinch gestures with scale physics
   */
  private handlePhysicsPinch(gesture: GestureInfo): void {
    if (!this.element || !gesture.scale) return;

    // Create smooth scale transition using our physics
    const scaleTransition = GSAPTimelineFactory.createScaleAnimation(
      this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
      {
        targetScale: gesture.scale,
        baseScale: 1.0,
        duration: 0.3,
        ease: 'power2.out',
      }
    );

    scaleTransition.play();
  }

  /**
   * Handle pan gestures with physics-driven smoothing
   */
  private handlePhysicsPan(gesture: GestureInfo): void {
    // Use velocity tracker for smooth pan physics
    const velocity = this.velocityTracker.getVelocity();
    
    // Apply kinetic physics for natural movement
    const dragScale = this.kineticPhysics.calculateDragScale(
      gesture.distance,
      velocity.velocity
    );

    // Create physics-driven movement feedback
    if (this.element) {
      const panTimeline = GSAPTimelineFactory.createDragEffect(
        this.element as unknown as Sprite, // Architectural bridge: DOM → PIXI
        gesture.distance,
        dragScale * 0.1 // Scale intensity
      );

      panTimeline.play();
    }

    // Trigger drag move callback with physics-enhanced data
    this.callbacks?.onDragMove(
      gesture.currentPoint.x,
      gesture.currentPoint.y,
      gesture.currentPoint.x - gesture.startPoint.x,
      gesture.currentPoint.y - gesture.startPoint.y
    );
  }

  /**
   * Enable input handling
   */
  enable(): void {
    this.isEnabled = true;
  }

  /**
   * Disable input handling
   */
  disable(): void {
    this.isEnabled = false;
  }

  /**
   * Set input configuration
   */
  setInputConfig(config: Partial<InputConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current input configuration
   */
  getInputConfig(): InputConfig {
    return { ...this.config };
  }

  /**
   * Destroy input controller and cleanup all enhanced components
   */
  destroy(): void {
    // Clean up enhanced components
    this.gestureRecognizer?.destroy();
    this.gestureRecognizer = null;

    this.keyboardNavigator?.destroy();
    this.keyboardNavigator = null;

    this.eventThrottler?.destroy();

    // Clean up legacy event listeners
    this.removeEventListeners();
    
    // Reset state
    this.element = null;
    this.callbacks = null;
    this.isEnabled = false;
  }

  /**
   * Setup all event listeners with proper options
   */
  private setupEventListeners(): void {
    if (!this.element) return;

    // Mouse events
    if (this.config.enableMouse) {
      this.addEventListenerWithCleanup(EVENT_NAMES.MOUSE_DOWN, (e) =>
        this.handlePointerStart(e as MouseEvent)
      );
      this.addEventListenerWithCleanup(
        EVENT_NAMES.MOUSE_MOVE,
        (e) => this.handlePointerMove(e as MouseEvent),
        { passive: true }
      );
      this.addEventListenerWithCleanup(EVENT_NAMES.MOUSE_UP, (e) =>
        this.handlePointerEnd(e as MouseEvent)
      );
      this.addEventListenerWithCleanup(EVENT_NAMES.MOUSE_LEAVE, (e) =>
        this.handlePointerEnd(e as MouseEvent)
      );
    }

    // Touch events
    if (this.config.enableTouch) {
      this.addEventListenerWithCleanup(
        EVENT_NAMES.TOUCH_START,
        (e) => this.handleTouchStart(e as TouchEvent),
        { passive: false }
      );
      this.addEventListenerWithCleanup(
        EVENT_NAMES.TOUCH_MOVE,
        (e) => this.handleTouchMove(e as TouchEvent),
        { passive: true }
      );
      this.addEventListenerWithCleanup(EVENT_NAMES.TOUCH_END, (e) =>
        this.handleTouchEnd(e as TouchEvent)
      );
      this.addEventListenerWithCleanup(EVENT_NAMES.TOUCH_CANCEL, (e) =>
        this.handleTouchEnd(e as TouchEvent)
      );
    }

    // Keyboard events (on document for global access)
    if (this.config.enableKeyboard) {
      const keyHandler = (e: Event): void =>
        this.handleKeyDown(e as KeyboardEvent);
      document.addEventListener(EVENT_NAMES.KEY_DOWN, keyHandler);
      this.boundHandlers.set(EVENT_NAMES.KEY_DOWN, keyHandler);
    }

    // Prevent context menu on touch devices
    this.addEventListenerWithCleanup(
      EVENT_NAMES.CONTEXT_MENU,
      (e: Event): void => {
        e.preventDefault();
      }
    );
  }

  /**
   * Remove all event listeners
   */
  private removeEventListeners(): void {
    if (!this.element) return;

    // Remove element events
    this.boundHandlers.forEach((handler, event) => {
      if (event === EVENT_NAMES.KEY_DOWN) {
        document.removeEventListener(event, handler);
      } else {
        this.element!.removeEventListener(event, handler);
      }
    });

    this.boundHandlers.clear();
  }

  /**
   * Helper to add event listener with cleanup tracking
   */
  private addEventListenerWithCleanup(
    event: string,
    handler: EventListener,
    options?: AddEventListenerOptions
  ): void {
    if (!this.element) return;

    this.element.addEventListener(event, handler, options);
    this.boundHandlers.set(event, handler);
  }

  /**
   * Handle mouse down events
   */
  private handlePointerStart(e: MouseEvent): void {
    if (!this.isEnabled || !this.callbacks) return;

    this.isPointerDown = true;
    this.startX = e.clientX;
    this.startY = e.clientY;
    this.currentX = e.clientX;
    this.currentY = e.clientY;
    this.startTime = performance.now();

    this.callbacks.onDragStart(this.startX, this.startY);

    // Prevent text selection
    e.preventDefault();
  }

  /**
   * Handle mouse move events
   */
  private handlePointerMove(e: MouseEvent): void {
    if (!this.isEnabled || !this.isPointerDown || !this.callbacks) return;

    const deltaX = e.clientX - this.currentX;
    const deltaY = e.clientY - this.currentY;

    this.currentX = e.clientX;
    this.currentY = e.clientY;

    this.callbacks.onDragMove(this.currentX, this.currentY, deltaX, deltaY);
  }

  /**
   * Handle mouse up events
   */
  private handlePointerEnd(_e: MouseEvent): void {
    if (!this.isEnabled || !this.isPointerDown || !this.callbacks) return;

    this.isPointerDown = false;

    const deltaX = this.currentX - this.startX;
    const deltaTime = performance.now() - this.startTime;

    // Calculate velocity for momentum
    const velocity = Math.abs(deltaX) / deltaTime;

    // Check for swipe gesture
    if (
      Math.abs(deltaX) > this.config.swipeThreshold &&
      velocity > PHYSICS.VELOCITY_THRESHOLD
    ) {
      if (deltaX > 0) {
        this.callbacks.onSwipeRight();
      } else {
        this.callbacks.onSwipeLeft();
      }
    }

    this.callbacks.onDragEnd(this.currentX, this.currentY);
  }

  /**
   * Handle touch start events
   */
  private handleTouchStart(e: TouchEvent): void {
    if (!this.isEnabled || !this.callbacks) return;

    // Only handle single touch
    if (e.touches.length !== 1) return;

    const touch = e.touches[0];
    this.isPointerDown = true;
    this.startX = touch.clientX;
    this.startY = touch.clientY;
    this.currentX = touch.clientX;
    this.currentY = touch.clientY;
    this.startTime = performance.now();

    this.callbacks.onDragStart(this.startX, this.startY);

    // Prevent scrolling on vertical swipes within threshold
    if (Math.abs(this.startY - touch.clientY) < this.config.dragThreshold) {
      e.preventDefault();
    }
  }

  /**
   * Handle touch move events
   */
  private handleTouchMove(e: TouchEvent): void {
    if (!this.isEnabled || !this.isPointerDown || !this.callbacks) return;

    if (e.touches.length !== 1) return;

    const touch = e.touches[0];
    const deltaX = touch.clientX - this.currentX;
    const deltaY = touch.clientY - this.currentY;

    this.currentX = touch.clientX;
    this.currentY = touch.clientY;

    this.callbacks.onDragMove(this.currentX, this.currentY, deltaX, deltaY);
  }

  /**
   * Handle touch end events
   */
  private handleTouchEnd(_e: TouchEvent): void {
    if (!this.isEnabled || !this.isPointerDown || !this.callbacks) return;

    this.isPointerDown = false;

    const deltaX = this.currentX - this.startX;
    const deltaTime = performance.now() - this.startTime;

    // Calculate velocity for momentum
    const velocity = Math.abs(deltaX) / deltaTime;

    // Check for swipe gesture
    if (
      Math.abs(deltaX) > this.config.swipeThreshold &&
      velocity > PHYSICS.VELOCITY_THRESHOLD
    ) {
      if (deltaX > 0) {
        this.callbacks.onSwipeRight();
      } else {
        this.callbacks.onSwipeLeft();
      }
    }

    this.callbacks.onDragEnd(this.currentX, this.currentY);
  }

  /**
   * Handle keyboard events
   */
  private handleKeyDown(e: KeyboardEvent): void {
    if (!this.isEnabled || !this.callbacks) return;

    // Only handle if no input elements are focused
    const activeElement = document.activeElement;
    if (
      activeElement &&
      (activeElement.tagName === HTML_TAGS.INPUT ||
        activeElement.tagName === HTML_TAGS.TEXTAREA ||
        activeElement.tagName === HTML_TAGS.SELECT ||
        activeElement.getAttribute(HTML_ATTRIBUTES.CONTENT_EDITABLE) ===
          HTML_ATTRIBUTES.TRUE)
    ) {
      return;
    }

    switch (e.key) {
      case KEYBOARD_KEYS.ARROW_LEFT:
      case 'a':
      case 'A':
        this.callbacks.onKeyLeft();
        e.preventDefault();
        break;
      case KEYBOARD_KEYS.ARROW_RIGHT:
      case 'd':
      case 'D':
        this.callbacks.onKeyRight();
        e.preventDefault();
        break;
    }
  }
}
